class Station(
    val key: String, val name: String, val pts: FloatArray, val lat: Double,
    val lon: Double, val lines: Int, val anchor: Char, val dx: Float, val dy: Float,
    val priority: Int, val crl: Boolean, platformSpec: String,
) {
    val x = (0 until pts.size / 2).map { pts[it * 2] }.average().toFloat()
    val y = (0 until pts.size / 2).map { pts[it * 2 + 1] }.average().toFloat()
    /** platform stop id -> platform number */
    val platforms: Map<String, String> = platformSpec.split(';').filter { it.isNotEmpty() }
        .associate { it.substringBefore('=') to it.substringAfter('=') }
    val interchange get() = pts.size > 2 || crl
}

class Seg(val line: Int, val from: Int, val to: Int, val poly: FloatArray,
          val lat0: Double, val lon0: Double, val lat1: Double, val lon1: Double)

internal fun f(s: String): FloatArray = s.split(',').map { it.toFloat() }.toFloatArray()
